/* Serializable village defenders. No rendering, wall clock or random rerolls on retry. */
(function(root){
 const CONFIG=Object.freeze({heroOpponents:[3,5,7],residentOpponents:2,casualtyAt:24,preparedLosses:1,unpreparedLosses:2,maxResidentAttackers:4,maxHeroAttackers:7});
 const STORY_IDS=['marfa','erema','prokop','dunyasha','frol','agafya'];
 const BACKGROUND=['Мирон','Савва','Лада','Ульяна','Тихон','Аксинья','Назар'];
 const SITES=[[-23,-10],[18,3],[24,-18],[-25,17],[14,23],[23,14],[-18,-27],[28,-9],[-22,28],[8,-30],[32,20],[-30,6],[7,29]];
 function ensure(g){g.villagers??=[];g.story??={};g.residentCombat??={schema:1,rosterAdded:false,seed:0};const c=g.residentCombat;if(!c.rosterAdded&&(!g.villageId||g.villageId==='vyselki')){c.rosterAdded=true;for(let i=0;i<7;i++){const id='background-'+i;if(!g.villagers.some(v=>v.id===id))g.villagers.push({id,name:BACKGROUND[i],role:i%3===0?'отшельник':'житель',job:['wood','stone','grain',null][i%4],quote:'Не готов говорить о прошлом деревни.',fear:28,storyActive:false,alive:true});}}
 g.villagers.forEach((v,i)=>{v.storyActive??=STORY_IDS.includes(v.id);v.alive??=true;v.combatHp??=v.storyActive?8:5;v.combatMaxHp??=v.storyActive?8:5;v.scenePosition??={x:SITES[i%SITES.length][0],z:SITES[i%SITES.length][1]};});g.story.residentLosses??=[];return c;}
 const living=g=>(g.villagers||[]).filter(v=>v.alive!==false);
 function roll(seed){let n=seed>>>0;return ()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296};}
 function protection(g,v){const repairs=Object.values(g.villageProgress?.repairs||{});const home=!!v.home&&(repairs.some(r=>r.id==='house_ruin'&&r.x===v.home.x&&r.z===v.home.z)||(g.villageLayout||[]).some(o=>o.id==='hut'&&o.x===v.home.x&&o.z===v.home.z));const listened=v.storyActive?(g.villageProgress?.talked||[]).includes(v.id):false;const pos=v.scenePosition||{x:0,z:0};const light=g.defense?.fueledTotems>0&&(g.villageLayout||[]).some(o=>o.id==='totem'&&Math.hypot(pos.x-o.x,pos.z-o.z)<=7);return Number(home)+Number(listened)+Number(light);}
 function wellPrepared(g){return Object.values(g.villageProgress?.repairs||{}).filter(r=>r.id==='house_ruin').length>=2&&(g.villageProgress?.talked||[]).filter(id=>STORY_IDS.includes(id)).length>=3;}
 function slots(g,wave){ensure(g);return [...living(g).flatMap(v=>Array.from({length:CONFIG.residentOpponents},()=>({targetResident:v.id}))),...Array.from({length:CONFIG.heroOpponents[Math.min(2,Math.max(0,wave-1))]},()=>({targetResident:null}))];}
 function begin(g){const c=ensure(g),d=g.defense;if(!d)return;const random=roll(c.seed=(c.seed||Math.floor(Math.random()*4294967295))>>>0);const pool=living(g).filter(v=>!v.storyActive);const desired=wellPrepared(g)?CONFIG.preparedLosses:CONFIG.unpreparedLosses;const victims=pool.map(v=>({v,rank:protection(g,v)*.5+random()})).sort((a,b)=>a.rank-b.rank).slice(0,desired).map(x=>x.v.id);d.residentBattle={schema:1,victims,quota:victims.length,losses:[],kills:0,transfers:0,pressure:g.story.residentLosses.length,seed:c.seed};
 for(const v of living(g)){const post=(g.villageProgress?.guards||[]).find(p=>p.id===v.id&&(g.villageLayout||[]).some(t=>t.id==='tower'&&t.x===p.x&&t.z===p.z));if(post)v.scenePosition={x:post.x+3,z:post.z+3};v.combatHp=v.combatMaxHp+protection(g,v)*2;v.combatDown=false;v.combatAttackAt=0;v.combatHurtAt=0;v.combatKills=0;}
 const assignments=slots(g,d.wave);d.enemies.filter(e=>e.kind!=='leshy').forEach((e,i)=>{e.targetResident=assignments[i]?.targetResident??null;e.initialResident=e.targetResident;e.residentAssigned=true;});}
 function target(g,e){if(!e.residentAssigned)return undefined;if(e.targetResident&&living(g).some(v=>v.id===e.targetResident&&!v.combatDown))return e.targetResident;const available=living(g).filter(v=>!v.combatDown);const loads=new Map(available.map(v=>[v.id,g.defense.enemies.filter(a=>a.hp>0&&a.targetResident===v.id).length]));const heroLoad=g.defense.enemies.filter(a=>a.hp>0&&a.kind!=='leshy'&&!a.targetResident).length;const nearest=available.filter(v=>loads.get(v.id)<CONFIG.maxResidentAttackers).sort((a,b)=>loads.get(a.id)-loads.get(b.id)||Math.hypot(a.scenePosition.x-e.x,a.scenePosition.z-e.z)-Math.hypot(b.scenePosition.x-e.x,b.scenePosition.z-e.z))[0];const next=e.targetResident?(nearest&&heroLoad>=CONFIG.maxHeroAttackers?nearest.id:heroLoad<CONFIG.maxHeroAttackers?null:nearest?.id??'reserve'):null;if(next!==e.targetResident){e.targetResident=next;e.route=[];e.retargetVersion=(e.retargetVersion||0)+1;g.defense.residentBattle.transfers++;}return e.targetResident;}
 function kill(g,id,reason='Не выдержал натиска нечисти'){const v=g.villagers.find(v=>v.id===id),b=g.defense?.residentBattle;if(!v||v.alive===false||v.storyActive||!b?.victims.includes(id))return false;v.alive=false;v.combatHp=0;v.job=null;v.diedWave=g.defense.wave;v.diedDay=g.day;const record={id:'resident-loss-'+g.defense.wave+'-'+id,residentId:id,name:v.name,day:g.day,wave:g.defense.wave,reason};if(!g.story.residentLosses.some(r=>r.id===record.id)){g.story.residentLosses.push(record);g.journal??=[];g.journal.push('Ночь '+record.wave+' · погиб '+v.name+'. '+reason+'.');}if(!b.losses.includes(id))b.losses.push(id);for(const e of g.defense.enemies)if(e.hp>0&&e.targetResident===id)target(g,e);return true;}
 function hit(g,id,damage=1){const v=g.villagers?.find(v=>v.id===id),d=g.defense;if(!v||v.alive===false||v.combatDown||!d?.residentBattle||d.stage!=='active'||d.elapsed<(v.combatHurtAt||0))return false;v.combatHurtAt=d.elapsed+2;v.combatHp=Math.max(0,v.combatHp-damage);if(!v.combatHp){if(!kill(g,id))v.combatDown=true;}return true;}
 function finishQuota(g){const b=g.defense?.residentBattle;if(!b)return;for(const id of b.victims)kill(g,id,'Погиб при защите деревни.');}
 function tick(g,dt,navigation){const d=g.defense,b=d?.residentBattle;if(g.phase!=='combat'||d.stage!=='active'||!b)return false;let changed=false;
 // Mandatory dramatic losses requested for this prototype: chosen once, only background NPCs.
 if(d.elapsed>=CONFIG.casualtyAt&&b.losses.length<b.quota){finishQuota(g);changed=true;}
 for(const v of living(g)){if(v.combatDown)continue;const pos=v.scenePosition;const enemies=d.enemies.filter(e=>e.hp>0&&e.kind!=='leshy'&&(e.targetResident===v.id||Math.hypot(e.x-pos.x,e.z-pos.z)<2.5)).sort((a,b)=>Math.hypot(a.x-pos.x,a.z-pos.z)-Math.hypot(b.x-pos.x,b.z-pos.z));const e=enemies[0];if(!e)continue;const dx=e.x-pos.x,dz=e.z-pos.z,dist=Math.hypot(dx,dz);const post=v.job==='guard'&&(g.villageProgress?.guards||[]).find(p=>p.id===v.id&&(g.villageLayout||[]).some(t=>t.id==='tower'&&t.x===p.x&&t.z===p.z));if(post)continue;const range=1.8;if(dist>range&&dist<8&&navigation){const step=Math.min(dist-range,dt*1.5),x=pos.x+dx/dist*step,z=pos.z+dz/dist*step,y=navigation.height(pos.x,pos.z);if(navigation.walkable(x,z,y,pos.x,pos.z)){pos.x=x;pos.z=z;}}else if(dist<=range&&d.elapsed>=(v.combatAttackAt||0)&&(!navigation||navigation.walkable(e.x,e.z,navigation.height(pos.x,pos.z),pos.x,pos.z))){v.combatAttackAt=d.elapsed+(v.job==='guard'?3.2:2.5);v.combatStrikeUntil=d.elapsed+.35;e.hp=Math.max(0,e.hp-(v.storyActive?1:.75)-protection(g,v)*.25);if(!e.hp){v.combatKills++;b.kills++;changed=true;}}}
 return changed;}
 function restore(g,checkpoint){if(!checkpoint?.residents)return;g.villagers=JSON.parse(JSON.stringify(checkpoint.residents));g.story.residentLosses=JSON.parse(JSON.stringify(checkpoint.residentLosses||[]));g.journal=JSON.parse(JSON.stringify(checkpoint.residentJournal||[]));const victims=g.defense.residentBattle?.victims||[],seed=g.defense.residentBattle?.seed;begin(g);g.defense.residentBattle.victims=victims;g.defense.residentBattle.quota=victims.length;g.defense.residentBattle.seed=seed;}
 function recover(g){for(const v of living(g)){const post=(g.villageProgress?.guards||[]).find(p=>p.id===v.id&&(g.villageLayout||[]).some(t=>t.id==='tower'&&t.x===p.x&&t.z===p.z));if(post)v.scenePosition={x:post.x+3,z:post.z+3};v.combatHp=v.combatMaxHp;v.combatDown=false;}if(g.residentCombat)g.residentCombat.seed=(Math.imul(g.residentCombat.seed||1,1664525)+1013904223)>>>0;}
 const api={CONFIG,ensure,living,slots,begin,target,hit,kill,tick,finishQuota,restore,recover,protection,wellPrepared};root.ResidentCombat=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
